create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,category text not null,subcategory text default '',price numeric default 0,grams numeric default 0,hours numeric default 0,extra numeric default 0,labor numeric default 0,photo_path text,created_at timestamptz default now());
create table if not exists public.app_settings(id integer primary key check(id=1),spool_price numeric default 20,spool_weight numeric default 1000,machine_hourly numeric default 1,waste_pct numeric default 10);
insert into public.app_settings(id) values(1) on conflict do nothing;
alter table public.products enable row level security; alter table public.app_settings enable row level security;
create policy "forge3d products select" on public.products for select to authenticated using(lower(coalesce(auth.jwt()->>'email','')) in ('henrique.olivads@gmail.com','mayarasalencar@gmail.com'));
create policy "forge3d products insert" on public.products for insert to authenticated with check(lower(coalesce(auth.jwt()->>'email','')) in ('henrique.olivads@gmail.com','mayarasalencar@gmail.com'));
create policy "forge3d products update" on public.products for update to authenticated using(lower(coalesce(auth.jwt()->>'email','')) in ('henrique.olivads@gmail.com','mayarasalencar@gmail.com')) with check(lower(coalesce(auth.jwt()->>'email','')) in ('henrique.olivads@gmail.com','mayarasalencar@gmail.com'));
create policy "forge3d products delete" on public.products for delete to authenticated using(lower(coalesce(auth.jwt()->>'email','')) in ('henrique.olivads@gmail.com','mayarasalencar@gmail.com'));
create policy "forge3d settings read" on public.app_settings for select to authenticated using(lower(coalesce(auth.jwt()->>'email','')) in ('henrique.olivads@gmail.com','mayarasalencar@gmail.com'));
create policy "forge3d settings write" on public.app_settings for all to authenticated using(lower(coalesce(auth.jwt()->>'email','')) in ('henrique.olivads@gmail.com','mayarasalencar@gmail.com')) with check(lower(coalesce(auth.jwt()->>'email','')) in ('henrique.olivads@gmail.com','mayarasalencar@gmail.com'));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-photos','product-photos',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "forge3d photo access" on storage.objects for all to authenticated using(bucket_id='product-photos' and lower(coalesce(auth.jwt()->>'email','')) in ('henrique.olivads@gmail.com','mayarasalencar@gmail.com')) with check(bucket_id='product-photos' and lower(coalesce(auth.jwt()->>'email','')) in ('henrique.olivads@gmail.com','mayarasalencar@gmail.com'));
